/**
 * Authentication Validation Schemas
 * Zod schemas for auth endpoints
 */

import { z } from 'zod';

// Login schema
export const loginSchema = z.object({
  body: z.object({
    federationId: z.string().min(3, 'Federation ID must be at least 3 characters'),
    passcode: z.string().min(6, 'Passcode must be at least 6 characters')
  })
});

// Signup schema
// Federation ID is auto-generated by backend, not provided by user
export const signupSchema = z.object({
  body: z.object({
    email: z.string().email('Invalid email address'),
    passcode: z.string().min(8, 'Passcode must be at least 8 characters').regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/, 'Passcode must contain at least one uppercase letter, one lowercase letter, and one number'),
    bankName: z.string().optional(),
    bankId: z.string().optional()
  })
});

// Refresh token schema
export const refreshTokenSchema = z.object({
  body: z.object({
    refreshToken: z.string().min(1, 'Refresh token is required')
  })
});

// Forgot password schema
export const forgotPasswordSchema = z.object({
  body: z.object({
    federationId: z.string().min(1, 'Federation ID is required').optional(),
    email: z.string().email('Invalid email address').optional()
  }).refine(data => data.federationId || data.email, {
    message: 'Either federationId or email is required'
  })
});

// Reset password schema
export const resetPasswordSchema = z.object({
  body: z.object({
    token: z.string().min(1, 'Reset token is required'),
    newPassword: z.string().min(8, 'Password must be at least 8 characters').regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/, 'Password must contain at least one uppercase letter, one lowercase letter, and one number')
  })
});

// Change password schema
export const changePasswordSchema = z.object({
  body: z.object({
    currentPassword: z.string().min(1, 'Current password is required'),
    newPassword: z.string().min(8, 'New password must be at least 8 characters').regex(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/, 'New password must contain at least one uppercase letter, one lowercase letter, and one number')
  })
});
